#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Sets up R2 for one Mac (docs/DATA.md "Setting up R2"). Robby runs it once with the
# Cloudflare steps. Marti, or anyone on a new Mac, runs it with the key Robby sent them.

R2_DASH="https://dash.cloudflare.com/?to=/:account/r2"

# The rclone remote `r2` is defined only by these variables in .env, so no rclone.conf holds a key.
export_r2() {
  export RCLONE_CONFIG_R2_TYPE RCLONE_CONFIG_R2_PROVIDER RCLONE_CONFIG_R2_ENDPOINT \
    RCLONE_CONFIG_R2_ACCESS_KEY_ID RCLONE_CONFIG_R2_SECRET_ACCESS_KEY RCLONE_CONFIG_R2_NO_CHECK_BUCKET
}

ask_endpoint() {
  while true; do
    ask RCLONE_CONFIG_R2_ENDPOINT "Paste the S3 API endpoint:"
    [[ "$RCLONE_CONFIG_R2_ENDPOINT" =~ ^https://[0-9a-f]{32}\.r2\.cloudflarestorage\.com/?$ ]] && break
    warn "That isn't an R2 endpoint. It looks like https://<32 hex characters>.r2.cloudflarestorage.com"
  done
  write_env RCLONE_CONFIG_R2_TYPE s3
  write_env RCLONE_CONFIG_R2_PROVIDER Cloudflare
  write_env RCLONE_CONFIG_R2_ENDPOINT "${RCLONE_CONFIG_R2_ENDPOINT%/}"
  write_env RCLONE_CONFIG_R2_NO_CHECK_BUCKET true
}

ask_own_key() {
  ask_secret RCLONE_CONFIG_R2_ACCESS_KEY_ID "Paste the Access Key ID:"
  ask_secret RCLONE_CONFIG_R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
  write_env RCLONE_CONFIG_R2_ACCESS_KEY_ID "$RCLONE_CONFIG_R2_ACCESS_KEY_ID"
  write_env RCLONE_CONFIG_R2_SECRET_ACCESS_KEY "$RCLONE_CONFIG_R2_SECRET_ACCESS_KEY"
}

token_steps() {
  local name="$1" buckets="$2"
  open_url "$R2_DASH/api-tokens"
  step "Click 'Create Account API token'."
  step "Token name: $name"
  step "Permissions: Object Read & Write"
  step "Specify bucket(s): Apply to specific buckets only, then pick $buckets"
  step "TTL: Forever. Leave client IP filtering empty."
  step "Click 'Create API Token'. The next page shows the Access Key ID and the"
  say  "  Secret Access Key once. Keep it open until this stage is done."
  note "If a label differs, the dashboard changed. Pick the closest option and tell Claude."
}

stage_install() {
  stage "Install rclone"
  if command -v rclone >/dev/null 2>&1; then
    say "rclone is installed: $(rclone version | head -n1)"
  elif command -v brew >/dev/null 2>&1 && confirm "Install rclone with Homebrew now?"; then
    brew install rclone
  else
    warn "Install rclone from https://rclone.org/install/ in another terminal."
    pause "Press Enter once 'rclone version' works."
  fi
  pause
}

stage_check() {
  stage "Check read and write"
  export_r2
  local probe
  probe="setup-check/$(date -u +%Y%m%dT%H%M%SZ)-$RANDOM.txt"
  say "Writing, reading and deleting r2:dinkdata/$probe"
  if ! echo "dinkdata setup check" | rclone rcat "r2:dinkdata/$probe" \
    || [[ "$(rclone cat "r2:dinkdata/$probe")" != "dinkdata setup check" ]] \
    || ! rclone deletefile "r2:dinkdata/$probe"; then
    warn "The check failed. Fix the endpoint or key and run the wizard again."
    exit 1
  fi
  printf '  %s✓ this Mac can read and write the dinkdata bucket%s\n' "$GREEN" "$RESET"
  pause
}

stage_upload_labels() {
  stage "Upload local labels"
  export_r2
  local count=0
  [[ -d labels ]] && count=$(find labels -type f ! -name '.*' | wc -l | tr -d ' ')
  if (( count == 0 )); then
    say "There is no local labels/ folder to upload."
  else
    say "labels/ has $count file(s). The studio saved them with R2's layout."
    note "--immutable never overwrites. It stops if a file in R2 differs from yours."
    if confirm "Copy them to r2:dinkdata/labels now?"; then
      rclone copy labels r2:dinkdata/labels --immutable --exclude '.*' --stats-one-line -v
      printf '  %s✓ uploaded%s\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("upload labels: uv run --env-file .env rclone copy labels r2:dinkdata/labels --immutable")
    fi
  fi
  pause
}

run_wizard() {

cd "$(git rev-parse --show-toplevel)"
# write_env keeps an existing file's mode, so make sure .env holding keys is readable only by you.
if [[ -e "$ENV_FILE" ]]; then chmod 600 "$ENV_FILE"; fi

printf '\n'
if confirm "Are you creating the buckets and keys in Cloudflare (Robby, once)?"; then
  CREATOR=1; TOTAL_STAGES=8
else
  CREATOR=0; TOTAL_STAGES=4
fi

banner "DinkData R2 setup"

stage_install

if (( CREATOR )); then
  stage "Create the two buckets"
  open_url "$R2_DASH/overview"
  step "Click 'Create bucket'. Name: dinkdata. Location: Automatic."
  say  "  Default storage class: Standard. Click 'Create bucket'."
  step "Go back to the R2 overview and do the same for: dinkdata-backup"
  step "Leave public access off on both."
  pause "Press Enter once both buckets are listed."

  stage "Account endpoint"
  open_url "$R2_DASH/overview"
  step "On the R2 overview, find 'Account Details' and copy the S3 API endpoint."
  ask_endpoint
  set_secret R2_ENDPOINT "$RCLONE_CONFIG_R2_ENDPOINT"
  pause

  stage "Your key"
  token_steps "dinkdata-robby" "dinkdata"
  ask_own_key
  pause

  stage "CI backup key"
  say "The nightly backup workflow uses this key. It goes to GitHub secrets only."
  token_steps "dinkdata-ci-backup" "dinkdata and dinkdata-backup"
  ask_secret CI_KEY_ID "Paste the Access Key ID:"
  ask_secret CI_KEY_SECRET "Paste the Secret Access Key:"
  set_secret R2_BACKUP_ACCESS_KEY_ID "$CI_KEY_ID"
  set_secret R2_BACKUP_SECRET_ACCESS_KEY "$CI_KEY_SECRET"
  unset CI_KEY_ID CI_KEY_SECRET
  pause

  stage "Marti's key"
  say "This wizard doesn't save Marti's key anywhere. Send it to Marti yourself."
  token_steps "dinkdata-marti" "dinkdata"
  step "Put the Access Key ID, the Secret Access Key and this endpoint in a"
  say  "  password manager item shared with Marti, or a disappearing Signal message:"
  say  "  $RCLONE_CONFIG_R2_ENDPOINT"
  warn "Never send it by email, Slack or GitHub."
  pause "Press Enter once Marti has it."
else
  stage "Paste your key"
  say "Use the endpoint and key Robby sent you."
  ask_endpoint
  ask_own_key
  pause
fi

stage_check
stage_upload_labels

finish
say "Use rclone with: uv run --env-file .env rclone lsf r2:dinkdata"
printf '\n'
}

run_wizard "$@"; exit
